package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.BufferKey;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveLong() throws IOException {
        long value = 123456789L;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        // Verify that the number was written to the generator
        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        long value = 0L;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_NegativeLong() throws IOException {
        long value = -987654321L;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_LongMaxValue() throws IOException {
        long value = Long.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_LongMinValue() throws IOException {
        long value = Long.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_Sequence() throws IOException {
        tokenBuffer.writeStartObject();
        tokenBuffer.writeFieldName("id");
        tokenBuffer.writeNumber(100L);
        tokenBuffer.writeFieldName("val");
        tokenBuffer.writeNumber(200L);
        tokenBuffer.writeEndObject();

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeStartObject();
        verify(gen).writeFieldName("id");
        verify(gen).writeNumber(100L);
        verify(gen).writeFieldName("val");
        verify(gen).writeNumber(200L);
        verify(gen).writeEndObject();
    }

    @Test
    public void testWriteNumber_WithParserConstructor() throws IOException {
        JsonParser parser = mock(JsonParser.class);
        TokenBuffer tb = new TokenBuffer(parser);
        tb.writeNumber(42L);

        JsonGenerator gen = mock(JsonGenerator.class);
        tb.serialize(gen);
        verify(gen).writeNumber(42L);
    }

    @Test
    public void testWriteNumber_WithParserAndContextConstructor() throws IOException {
        JsonParser parser = mock(JsonParser.class);
        com.fasterxml.jackson.databind.DeserializationContext ctxt = mock(com.fasterxml.jackson.databind.DeserializationContext.class);
        TokenBuffer tb = new TokenBuffer(parser, ctxt);
        tb.writeNumber(42L);

        JsonGenerator gen = mock(JsonGenerator.class);
        tb.serialize(gen);
        verify(gen).writeNumber(42L);
    }
}
